package com.testora.service;
import com.testora.dao.UserDAO; import com.testora.dto.ApiResponse; import com.testora.model.*; import com.testora.util.PasswordUtil; import java.util.regex.*;
/** Validates registration and login requests. */
public class AuthService {private final UserDAO users=new UserDAO(); public ApiResponse<User> login(String email,String password){try{var u=users.findByEmail(email);if(u.isPresent()&&PasswordUtil.matches(password,u.get().getPasswordHash()))return ApiResponse.ok("Welcome, "+u.get().getName(),u.get());return ApiResponse.fail("Invalid email or password.");}catch(Exception e){return ApiResponse.fail("Database error: "+e.getMessage());}}
 public ApiResponse<User> register(String name,String email,String password){try{if(name.isBlank()||!Pattern.matches("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$",email)||password.length()<8)return ApiResponse.fail("Enter name, valid email, and password of 8+ characters.");if(users.findByEmail(email).isPresent())return ApiResponse.fail("Email is already registered.");return ApiResponse.ok("Registration successful.",users.create(new User(0,name,email,PasswordUtil.hash(password),Role.STUDENT)));}catch(Exception e){return ApiResponse.fail("Could not register: "+e.getMessage());}} }
